from functools import lru_cache
tiles={(c,r) for r in [0,1,5,6] for c in [2,3,4]} | {(c,r) for r in [2,3,4] for c in range(5)}
init=frozenset({(3,1),(0,2),(1,2),(2,4)})
def moves(pegs):
 for c,r in pegs:
  for dc,dr in [(2,0),(-2,0),(0,2),(0,-2)]:
   dst=(c+2*dc//2,r+2*dr//2) # wrong intentional? 
   dst=(c+dc,r+dr); mid=(c+dc//2,r+dr//2)
   if dst in tiles and dst not in pegs and mid in pegs:
    yield (c,r),dst, frozenset((pegs-{(c,r),mid})|{dst})
def bfs(start):
 q=[(start,[])]; seen={start}
 for p,path in q:
  if len(p)==1:return path,p
  for s,d,n in moves(p):
   if n not in seen:seen.add(n);q.append((n,path+[(s,d)]))
print(bfs(init))

